func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi correttamente"):
		return

	var tower := find_by_name(main, "WatchTower")
	if not check("tower", tower != null, "Deve esistere il nodo WatchTower"):
		return

	check("has_count", has_function(tower, "count_lit_lanterns"), "WatchTower deve possedere la funzione count_lit_lanterns()")
	check("has_off", has_function(tower, "turn_off_all"), "WatchTower deve possedere la funzione turn_off_all()")

	var count = call_if_exists(tower, "count_lit_lanterns")
	check("initial_count", count == 2, "All'inizio ci sono esattamente 2 lanterne accese, count_lit_lanterns deve restituire 2")

	call_if_exists(tower, "turn_off_all")
	await wait_frames(2)

	var count_after = call_if_exists(tower, "count_lit_lanterns")
	check("after_off", count_after == 0, "Dopo turn_off_all(), count_lit_lanterns deve restituire 0")
